{
  "stages": {
    "prototype": {
      "level": 4,
      "rationale": "For disposable exploration in an isolated environment, speed and learning matter more than maintainability. Keep it away from sensitive data and production systems, and verify any result before relying on it beyond the experiment."
    },
    "proof-of-concept": {
      "level": 3,
      "rationale": "A demo can be built quickly with AI, but stakeholders may treat its behavior as evidence that the product is viable. Review changes selectively and test the claims and flows being demonstrated; label shortcuts and avoid presenting it as production-ready."
    },
    "mvp": {
      "level": 2,
      "rationale": "Real early users depend on the MVP, so a person should understand and review every change line by line before release. AI can still accelerate implementation, with tests and basic security checks supporting that review."
    },
    "production": {
      "level": 2,
      "rationale": "A maintained product with paying customers needs changes that teammates can understand, support, and audit. Review every change line by line, and require appropriate tests, security checks, and operational review before deployment."
    },
